from pathlib import Path
import pandas as pd


# ---------------------------------------------------------
# 1. DEFINE PROJECT LOCATION
# ---------------------------------------------------------

# Use the folder where this script is saved as the project root.
ROOT = Path(__file__).resolve().parent

# Folder containing the clean CSV files generated by the ETL.
ETL_DIR = ROOT / "project_001_ETL"

# Excel file to generate.
OUTPUT_FILE = ROOT / "Project_001_Manufacturing_Clean.xlsx"


# ---------------------------------------------------------
# 2. CLEAN TABLES TO INCLUDE
# ---------------------------------------------------------

clean_files = [
    "dim_date_clean.csv",
    "dim_machine_clean.csv",
    "dim_product_clean.csv",
    "dim_shift_clean.csv",
    "dim_downtime_clean.csv",
    "fact_production_clean.csv",
    "fact_downtime_clean.csv",
    "fact_maintenance_clean.csv",
]


# ---------------------------------------------------------
# 3. VERIFY THAT ALL FILES EXIST
# ---------------------------------------------------------

print("Starting Clean Excel generation...")
print()

missing_files = []

for filename in clean_files:
    file_path = ETL_DIR / filename

    if not file_path.exists():
        missing_files.append(filename)

if missing_files:
    print("ERROR: The following files were not found:")

    for filename in missing_files:
        print(f" - {filename}")

    print()
    print(f"Expected folder:")
    print(ETL_DIR)

    raise FileNotFoundError(
        "One or more clean CSV files are missing."
    )


# ---------------------------------------------------------
# 4. CREATE EXCEL WORKBOOK
# ---------------------------------------------------------

with pd.ExcelWriter(
    OUTPUT_FILE,
    engine="openpyxl"
) as writer:

    for filename in clean_files:

        file_path = ETL_DIR / filename

        # Read clean CSV.
        df = pd.read_csv(file_path)

        # Example:
        # dim_date_clean.csv -> dim_date
        sheet_name = filename.replace(
            "_clean.csv",
            ""
        )

        # Excel sheet names have a maximum length of 31 characters.
        sheet_name = sheet_name[:31]

        # Write the DataFrame to its own worksheet.
        df.to_excel(
            writer,
            sheet_name=sheet_name,
            index=False
        )

        print(
            f"Added: {sheet_name} "
            f"({len(df):,} rows)"
        )


# ---------------------------------------------------------
# 5. FINAL MESSAGE
# ---------------------------------------------------------

print()
print("Clean Excel generated successfully!")
print()
print(f"Output file:")
print(OUTPUT_FILE)
print()
print("Sheets created:")

for filename in clean_files:

    sheet_name = filename.replace(
        "_clean.csv",
        ""
    )

    print(f" - {sheet_name}")
